/* CloudLab — không gọi dịch vụ mạng, không có analytics. */
'use strict';
const K=CloudCore, BASE=window.CLOUD_DATA, KEY='cloudlab.personal.v1', CONTENT='cloudlab.content.v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
const $=s=>document.querySelector(s);let D=BASE,S=K.emptyState(),practice={},hints={},lastFocus=null,sourceURL=null,storageError='',searchCache=[];
try{const v=localStorage.getItem(CONTENT);if(v)D=K.mergeContent(BASE,JSON.parse(v));K.validateContent(D);const raw=localStorage.getItem(KEY);if(raw)S=K.validateBackup(JSON.parse(raw));}catch(e){storageError='Không nạp được một phần dữ liệu đã lưu: '+e.message+'. Dữ liệu gốc vẫn được giữ trong trình duyệt; hãy xuất dữ liệu trước khi thay đổi.';}
function persist(){if(storageError)return false;try{localStorage.setItem(KEY,JSON.stringify(S));return true;}catch(e){toast('Chưa lưu được: bộ nhớ trình duyệt đầy hoặc bị chặn. Hãy xuất sao lưu ngay.',true);return false;}}
function toast(s,error=false){const el=$('#toast');el.textContent=s;el.style.background=error?'#8c3037':'#142e39';el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',error?10000:3500);}
function units(c){return D.lessons.filter(l=>l.chapter===c);}
function li(id){return D.lessons.find(l=>l.id===id);}
function ch(id){return D.chapters.find(c=>c.id===id);}
function title(id){return li(id)?.title||id;}
function go(hash){closeModal();if(location.hash===hash)render();else location.hash=hash;}
function humanDate(t){return new Date(t).toLocaleString('vi-VN');}
function doneCount(c){return units(c).filter(l=>S.done[l.id]).length;}
function sourceRefs(refs=[]){return refs.map((r,i)=>`<div class="source"><strong>${esc(r.file)}</strong><br>Trang PDF ${r.start}${r.end!==r.start?'–'+r.end:''}${r.printed?' · trang in '+esc(r.printed):' · số trang của tệp PDF'}<br><button data-action="source" data-file="${esc(r.file)}" data-page="${r.start}">Mở đúng trang ↗</button></div>`).join('');}
function linkLesson(id){return `<a href="#lesson/${esc(id)}">${esc(id)} · ${esc(title(id))}</a>`;}
function buildIndex(){searchCache=[...D.lessons.map(l=>({kind:'Bài học',label:l.id+' · '+l.title,body:[l.title,l.problem,l.technical,l.plain,l.example,l.confusion,l.tradeoff,l.check].join(' '),url:'#lesson/'+l.id})),...D.terms.map(t=>({kind:'Thuật ngữ',label:t.name+' ('+t.en+')'+(t.abbr?' · '+t.abbr:''),body:[t.name,t.en,t.abbr,t.definition,t.plain,t.example,t.confusion].join(' '),term:t.id})),...D.questions.map(q=>({kind:'Câu hỏi',label:q.prompt,body:q.prompt+' '+q.options.join(' '),url:'#practice/'+q.chapter+'/'+q.lesson+'/0'}))].map(x=>({...x,normalized:norm(x.body)}));}
function annotated(text){
 const terms=D.terms.filter(t=>t.en||t.abbr||t.name).flatMap(t=>[t.en,t.abbr,t.name].filter(x=>x&&x.length>=3).map(word=>({word,id:t.id,t}))).sort((a,b)=>b.word.length-a.word.length);
 const found=[];const lower=text.toLowerCase();for(const {word,id,t} of terms){let p=lower.indexOf(word.toLowerCase());while(p>=0){const end=p+word.length;if(!/[\p{L}\p{N}]/u.test(text[p-1]||' ')&&!/[\p{L}\p{N}]/u.test(text[end]||' ')&&!found.some(f=>p<f.end&&end>f.start)){found.push({start:p,end,id,t});break;}p=lower.indexOf(word.toLowerCase(),p+1);}}
 found.sort((a,b)=>a.start-b.start);let out='',p=0;for(const f of found.slice(0,12)){out+=esc(text.slice(p,f.start));out+=`<button class="term" data-action="term" data-id="${esc(f.id)}" title="${esc(f.t.name+': '+f.t.definition)}">${esc(text.slice(f.start,f.end))}</button>`;p=f.end;}return out+esc(text.slice(p));
}
function nav(route,id){const items=[['home','⌂','Tổng quan'],['courses','▤','Chương & bài học'],['glossary','Aa','Từ điển thuật ngữ'],['practice','✓','Luyện tập'],['exams','◷','Thi thử 40 + 3'],['review','↺','Cần ôn lại'],['sources','▧','Tài liệu & đối chiếu'],['settings','⚙','Sao lưu & cập nhật']];$('#mainnav').innerHTML=items.map(([r,icon,label])=>`<a class="${route===r?'active':''}" href="#${r}"><span aria-hidden="true">${icon}</span> &nbsp;${label}</a>`).join('');const active=route==='lesson'?li(id)?.chapter:id;$('#course-nav').innerHTML=D.chapters.map(c=>`<a class="${active===c.id?'active':''}" href="#chapter/${esc(c.id)}">${doneCount(c.id)===units(c.id).length?'✓ ':''}${esc(c.id.replace('c','').replace(/^0/,''))} · ${esc(c.title)}</a>`).join('');$('#breadcrumb').textContent=route==='lesson'?(ch(li(id)?.chapter)?.title||'Bài học'):({home:'Không gian học tập',courses:'Lộ trình',chapter:'Chương & bài học',practice:'Thực hành có giải thích',exams:'Tự kiểm tra tổng hợp',exam:'Bài thi đang làm',result:'Kết quả & tự đánh giá',review:'Ôn tập chủ động',sources:'Nguồn học liệu',settings:'Dữ liệu của bạn',glossary:'Từ điển song ngữ'}[route]||'CloudLab');}
function chapterCards(){return D.chapters.map(c=>{const count=units(c.id).length,done=doneCount(c.id);return `<a class="card chapter-card" href="#chapter/${esc(c.id)}"><div class="number">${c.id.startsWith('c')?'CHƯƠNG '+c.id.slice(1):'MÔ-ĐUN BỔ TRỢ '+c.id.slice(1)}</div><h3>${esc(c.title)}</h3><p>${esc(c.questions[0])}</p><div class="progress"><i style="width:${100*done/count}%"></i></div><div class="row spread"><small>${done}/${count} bài đã học</small><span class="count">Mở chương →</span></div></a>`;}).join('');}
function home(){const done=D.lessons.filter(l=>S.done[l.id]).length,next=li(S.lastLesson)||D.lessons.find(l=>!S.done[l.id])||D.lessons[0],wrong=Object.values(S.wrong).filter(Boolean).length;return `<div class="eyebrow">KHÔNG GIAN HỌC CỦA BẠN</div><h1>Học để giải thích được.</h1><p class="lead">Đi từ vấn đề, hiểu cơ chế, rồi thử lập luận bằng chính lời của mình.</p><div class="hero"><div><div class="eyebrow">TIẾP TỤC LỘ TRÌNH</div><h2>${esc(next.title)}</h2><p>${esc(next.problem)}</p><a class="btn" href="#lesson/${esc(next.id)}">Tiếp tục học &nbsp; →</a></div><div class="hero-art" aria-hidden="true"><div class="stack"><span>ỨNG DỤNG</span><span>ĐIỀU PHỐI</span><span>ẢO HÓA</span><span>HẠ TẦNG</span></div></div></div><div class="grid four"><div class="card metric"><strong>${done}<small> / ${D.lessons.length}</small></strong><small>Bài bạn đã đánh dấu học</small><div class="progress"><i style="width:${done/D.lessons.length*100}%"></i></div></div><a class="card metric" href="#review"><strong>${wrong}</strong><small>Câu sai chờ luyện lại →</small></a><a class="card metric" href="#glossary"><strong>${D.terms.length}</strong><small>Thuật ngữ Việt · Anh · viết tắt →</small></a><a class="card metric" href="#exams"><strong>40 <small>+ 3</small></strong><small>Trắc nghiệm + tự luận mỗi đề →</small></a></div>${S.activeExam?`<div class="notice"><strong>Bạn có bài thi đang làm.</strong> Đồng hồ tiếp tục theo thời gian thực. <a href="#exam">Quay lại bài thi →</a></div>`:''}<div class="section-top"><h2>Lộ trình học</h2><a href="#courses">Xem toàn bộ ${D.chapters.length} nhóm →</a></div><div class="grid">${chapterCards()}</div><div class="notice">18 chương bám theo trục slide; 5 mô-đun bổ trợ được giữ riêng. Số mục là số điều hướng của ứng dụng. <a href="#sources">Xem nguồn và giới hạn diễn giải →</a></div>`;}
function coursePage(){return `<div class="eyebrow">BẢN ĐỒ KIẾN THỨC</div><h1>Từng chương, từng bước.</h1><p class="lead">Đọc mục tiêu có thể tự kiểm chứng, ôn lại tiên quyết rồi bắt đầu từng cụm slide. Không cần học các mô-đun theo thứ tự tệp được tải lên.</p><div class="section-top"><h2>18 chương theo trục slide + 5 mô-đun bổ trợ</h2></div><div class="grid">${chapterCards()}</div>`;}
function chapterPage(id){const c=ch(id);if(!c)return missing();return `<div class="eyebrow">${c.id.startsWith('c')?'CHƯƠNG '+c.id.slice(1):'MÔ-ĐUN BỔ TRỢ '+c.id.slice(1)}</div><h1>${esc(c.title)}</h1><p class="lead">${esc(c.context)}</p><div class="grid two" style="margin-top:25px"><div class="card"><h3>Chương này trả lời gì?</h3><ul>${c.questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h3>Bạn có thể tự chứng minh bằng cách…</h3><ul>${c.goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><div class="notice"><strong>Trước khi học:</strong> ${c.prior.length?c.prior.map(linkLesson).join(' · '):'Không yêu cầu bài tiên quyết trong ứng dụng. Cần kỹ năng sử dụng máy tính và đọc sơ đồ cơ bản.'}</div><div class="row spread"><h2>Các bài học</h2><a class="btn" href="#practice/${esc(c.id)}/all/0">Luyện chương này →</a></div><ol class="lesson-list">${units(c.id).map(l=>`<li><span class="lid">${esc(l.id)}</span><div>${linkLesson(l.id)}<small>${esc(l.problem.slice(0,140))}</small></div><span class="status">${S.done[l.id]?'✓ Đã học':'Chưa đánh dấu'}</span></li>`).join('')}</ol><div class="notice">Nguồn trục: <strong>${esc(c.source)}</strong>. Các bài gộp các trang liên tiếp theo chủ đề, không tự coi số điều hướng là số mục gốc. Sách và tài liệu phụ được nêu riêng tại từng bài.</div>`;}
const sections=[['problem','Vấn đề cần giải quyết'],['technical','Giải thích kỹ thuật'],['plain','Nói dễ hiểu'],['example','Ví dụ từng bước'],['confusion','Điểm dễ nhầm'],['tradeoff','Giới hạn & đánh đổi']];
function lessonPage(id){const l=li(id);if(!l)return missing();S.lastLesson=id;persist();const siblings=units(l.chapter),pos=siblings.indexOf(l),terms=D.terms.filter(t=>t.lesson===id);return `<div class="eyebrow">${esc(ch(l.chapter).title)}</div><div class="row spread"><h1>${esc(id)} · ${esc(l.title)}</h1></div><div class="actions"><button data-action="done" data-id="${esc(id)}" class="${S.done[id]?'primary':''}">${S.done[id]?'✓ Đã học · bỏ đánh dấu':'Đánh dấu đã học'}</button><button data-action="save" data-id="${esc(id)}">${S.saved[id]?'★ Đã lưu':'☆ Lưu bài'}</button><a class="btn" href="#practice/${esc(l.chapter)}/${esc(id)}/0">Tự luyện bài này →</a><button data-action="print">In bài</button></div><div class="lesson-layout"><article class="reading"><div class="notice" style="margin-top:0">Bài tiếng Việt: biên soạn/diễn giải theo nguồn ở cuối trang. Ví dụ tự xây dựng dùng dữ kiện giả định, không phải trích nguyên văn slide.</div>${sections.map(([key,label])=>`<section id="sec-${key}"><div class="label">${key==='example'?'VÍ DỤ VÀ DIỄN GIẢI THEO NHÃN TRONG ĐOẠN':key==='plain'?'DIỄN GIẢI BỔ SUNG':'HỌC LIỆU BIÊN SOẠN'}</div><h2>${label}</h2>${key==='example'&&l[key].includes('FROM python')?`<pre>${esc(l[key])}</pre>`:`<p>${annotated(l[key])}</p>`}</section>`).join('')}${labFor(id)}<section id="sec-related"><h2>Liên hệ kiến thức</h2><ul>${(l.related||[]).filter(x=>li(x)).map(x=>`<li>${linkLesson(x)}</li>`).join('')}</ul><p>Thuật ngữ trong bài:</p>${terms.map(t=>`<button class="pill" data-action="term" data-id="${esc(t.id)}">${esc(t.name)}${t.abbr?' · '+esc(t.abbr):''}</button>`).join(' ')}</section><section id="sec-check"><h2>Tự kiểm tra bằng lời của bạn</h2><p>${esc(l.check)}</p><details><summary>Gợi ý lập luận trước khi xem lại</summary><p>Xác định đối tượng và giả định trong câu hỏi. Vẽ các bước hoặc lớp liên quan, giải thích quan hệ nhân–quả rồi kiểm tra một trường hợp giới hạn. Đối chiếu phần cơ chế, ví dụ và điểm dễ nhầm của chính bài này.</p></details><a href="#practice/${esc(l.chapter)}/${esc(id)}/0">Thử câu trắc nghiệm có phản hồi →</a></section><section id="sec-source"><h2>Nguồn để tra lại</h2><p class="muted">Trang PDF bắt đầu từ 1. Trang in sách được ghi riêng, không dùng thay số trang PDF.</p>${sourceRefs(l.refs)}</section><div class="actions">${siblings[pos-1]?`<a class="pill" href="#lesson/${esc(siblings[pos-1].id)}">← Bài trước</a>`:''}<a class="pill" href="#chapter/${esc(l.chapter)}">Mục lục chương</a>${siblings[pos+1]?`<a class="pill" href="#lesson/${esc(siblings[pos+1].id)}">Bài tiếp →</a>`:''}</div></article><aside class="sticky"><div class="card toc"><h4>Trong bài này</h4>${sections.map(([k,t])=>`<a href="#sec-${k}" data-scroll="sec-${k}">${t}</a>`).join('')}<a href="#sec-related" data-scroll="sec-related">Liên hệ & thuật ngữ</a><a href="#sec-check" data-scroll="sec-check">Tự kiểm tra</a><a href="#sec-source" data-scroll="sec-source">Nguồn tham khảo</a><hr><small>${pos+1}/${siblings.length} bài trong chương</small></div><div class="card" style="margin-top:18px"><h4>Ghi chú của bạn</h4><label class="sr-only" for="note">Ghi chú cá nhân</label><textarea id="note" class="note" data-note="${esc(id)}" placeholder="Viết lại điều bạn hiểu, câu hỏi còn vướng…">${esc(S.notes[id]||'')}</textarea><small>Tự lưu khi nhập · riêng trên trình duyệt này</small></div></aside></div>`;}
function labFor(id){if(['2.1','10.2','13.2'].includes(id))return `<div class="lab"><div class="eyebrow">THỬ THAY ĐỔI THAM SỐ · MÔ HÌNH ĐƠN GIẢN</div><h3>Đủ compute chưa chắc đủ năng lực.</h3><label>Tải yêu cầu/giây <input type="range" min="100" max="1200" step="50" value="500" data-lab="load"></label><label>Năng lực DB (yêu cầu/giây) <input type="range" min="100" max="1200" step="50" value="400" data-lab="db"></label><div id="scale-out"></div><small>Giả định mỗi web replica xử lý 100 yêu cầu/giây, một truy vấn DB mỗi yêu cầu, chia tải lý tưởng. Chưa mô phỏng thời gian khởi tạo và lỗi.</small></div>`;
 if(['F1.4','1.2','11.1'].includes(id))return `<div class="lab"><div class="eyebrow">THỬ Amdahl · workload cố định</div><label>Phần song song (%) <input type="range" min="0" max="99" value="90" data-lab="parallel"></label><label>Số bộ xử lý <input type="range" min="1" max="128" value="8" data-lab="cpus"></label><div id="amdahl-out" class="lab-output"></div><small>Không tính overhead, cache hay mất cân bằng. Kết quả là mô hình lý tưởng.</small></div>`;
 if(id==='11.2')return `<div class="lab"><div class="eyebrow">KHÁM PHÁ MAPREDUCE</div><label for="word-input">Dữ liệu đầu vào (phân cách từ bằng khoảng trắng)</label><input id="word-input" type="text" value="mây nhanh mây" data-lab="words"><div id="word-out"></div><small>Mô phỏng theo từ đã chuyển chữ thường; không phải tokenizer ngôn ngữ tự nhiên hay Hadoop thật.</small></div>`;
 if(id==='F4.1')return `<div class="lab"><div class="eyebrow">MÔ PHỎNG XÁC SUẤT QUBIT ĐƠN</div><label>P(1) (%) <input type="range" min="0" max="100" value="25" data-lab="prob"></label><div id="qubit-out"></div><small>Chỉ xét biên độ thực không âm và phép đo cơ sở tính toán. Không mô phỏng pha, rối hay thiết bị QPU.</small></div>`;return '';}
function refreshLabs(){if($('#scale-out')){const load=+$('[data-lab=load]').value,db=+$('[data-lab=db]').value;$('#scale-out').innerHTML=`<div class="lab-output">${load} yêu cầu/s → cần ít nhất ${Math.ceil(load/100)} web replica</div><p>DB: ${db} yêu cầu/s. ${load>db?'<strong class="warning-dot">DB đang là giới hạn: thêm web chưa đủ.</strong>':'Theo giả định, DB đủ năng lực cho tải này.'}</p>`;}if($('#amdahl-out')){const p=+$('[data-lab=parallel]').value/100,n=+$('[data-lab=cpus]').value;$('#amdahl-out').textContent=`p=${(p*100).toFixed(0)}%, N=${n} → tăng tốc ${(1/(1-p+p/n)).toFixed(2)} lần · trần ${(1/(1-p)).toFixed(2)} lần`;}if($('#word-out')){const words=$('#word-input').value.trim().toLowerCase().split(/\s+/).filter(Boolean).slice(0,50),counts=Object.create(null);for(const w of words)counts[w]=(counts[w]||0)+1;$('#word-out').innerHTML=`<p>Map: ${words.map(w=>`(${esc(w)}, 1)`).join(' · ')}</p><p>Group: ${Object.entries(counts).map(([w,n])=>`${esc(w)}: [${Array(n).fill('1').join(', ')}]`).join(' · ')}</p><div class="cells">${Object.entries(counts).map(([w,n])=>`<span>Reduce: ${esc(w)} → ${n}</span>`).join('')}</div>`;}if($('#qubit-out')){const p=+$('[data-lab=prob]').value/100;$('#qubit-out').innerHTML=`<div class="lab-output">P(0)=${((1-p)*100).toFixed(0)}% · P(1)=${(p*100).toFixed(0)}%</div><p>α=√(1−p)≈${Math.sqrt(1-p).toFixed(3)}, β=√p≈${Math.sqrt(p).toFixed(3)}. Một shot trả một bit, không trả cả hai biên độ.</p>`;}}
function missing(){return '<h1>Chưa tìm thấy nội dung</h1><p>Liên kết có thể thuộc gói học liệu chưa được nhập.</p><a class="btn" href="#courses">Về lộ trình</a>';}
function glossaryPage(){return `<div class="eyebrow">TRA CỨU SONG NGỮ</div><h1>Hiểu từ, nối được ý.</h1><p class="lead">Tìm bằng tiếng Việt không dấu, tiếng Anh hoặc chữ viết tắt. Bấm thuật ngữ để xem ví dụ, điểm dễ nhầm và nguồn.</p><div class="filters"><label class="sr-only" for="term-search">Tìm thuật ngữ</label><input type="search" id="term-search" placeholder="Ví dụ: co gian, elasticity, VM…"><select id="term-chapter" aria-label="Lọc thuật ngữ theo chương"><option value="all">Tất cả chủ đề</option>${D.chapters.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('')}</select></div><p id="term-count" class="count"></p><div class="grid" id="term-results"></div>`;}
function filterTerms(){if(!$('#term-results'))return;const query=norm($('#term-search').value),c=$('#term-chapter').value;const ts=D.terms.filter(t=>(c==='all'||li(t.lesson)?.chapter===c)&&norm([t.name,t.en,t.abbr,t.definition].join(' ')).includes(query));$('#term-count').textContent=ts.length+' thuật ngữ';$('#term-results').innerHTML=ts.map(t=>`<div class="card term-card"><h3>${esc(t.name)}</h3><div class="en">${esc(t.en)}${t.abbr?' · '+esc(t.abbr):''}</div><p>${esc(t.definition)}</p><button data-action="term" data-id="${esc(t.id)}">Xem giải thích & ví dụ →</button></div>`).join('')||'<div class="empty">Không có kết quả. Thử tiếng Anh hoặc từ ngắn hơn.</div>';}
function showModal(html){lastFocus=document.activeElement;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();if(sourceURL){URL.revokeObjectURL(sourceURL);sourceURL=null;}if(lastFocus?.isConnected)lastFocus.focus();}
function showTerm(id){const t=D.terms.find(x=>x.id===id);if(!t)return;showModal(`<div class="eyebrow">TỪ ĐIỂN · ${esc(t.lesson)}</div><h2>${esc(t.name)} <small>(${esc(t.en)})</small></h2>${t.abbr?`<span class="tag">${esc(t.abbr)} = ${esc(t.en)}</span>`:''}<h3 style="margin-top:20px">Định nghĩa kỹ thuật</h3><p>${esc(t.definition)}</p><h3>Nói dễ hiểu trong ngữ cảnh bài</h3><p>${esc(t.plain)}</p><h3>Ví dụ liên quan trong bài</h3><p style="white-space:pre-line">${esc(t.example)}</p><h3>Điểm dễ nhầm</h3><p>${esc(t.confusion)}</p><p>${linkLesson(t.lesson)}</p>${sourceRefs(li(t.lesson)?.refs)}`);}
function showSearch(){showModal(`<div class="eyebrow">TÌM TOÀN BỘ HỌC LIỆU</div><h2>Bạn đang muốn hiểu điều gì?</h2><label class="sr-only" for="global-search">Từ khóa tìm kiếm</label><input id="global-search" type="search" placeholder="Từ khóa tiếng Việt/Anh, có hoặc không dấu…" style="width:100%"><p class="muted" style="margin-top:12px">Tìm trong bài giảng, ví dụ, thuật ngữ và câu hỏi. Để đọc nguyên bản từng PDF, dùng khu vực Tài liệu.</p><div id="search-results"></div>`);$('#global-search').focus();}
function search(){const raw=$('#global-search').value,q=norm(raw).trim();if(!q){$('#search-results').innerHTML='';return;}const words=q.split(/\s+/),res=searchCache.filter(x=>words.every(w=>x.normalized.includes(w)));$('#search-results').innerHTML=`<p class="count">${res.length} kết quả · hiển thị tối đa 60</p>`+res.slice(0,60).map(x=>`<div class="result-item"><span class="tag">${x.kind}</span><h3>${x.term?`<button class="quiet" data-action="term" data-id="${esc(x.term)}">${esc(x.label)}</button>`:`<a data-action="navigate" data-hash="${esc(x.url)}" href="${esc(x.url)}">${esc(x.label)}</a>`}</h3><small>${esc(x.body.slice(0,200))}…</small></div>`).join('');}
function recordAnswer(q,choice){const ok=choice===q.answer;S.stats[q.lesson]??={correct:0,total:0};S.stats[q.lesson].total++;S.stats[q.lesson].correct+=ok?1:0;if(ok)delete S.wrong[q.id];else S.wrong[q.id]=true;persist();}
function optionsHTML(q,choice,reveal,mode){const order=q.order||K.shuffle([0,1,2,3],'practice-'+q.id);return order.map((idx,n)=>`<label class="option ${choice===idx?'selected':''} ${reveal?(idx===q.answer?'correct':choice===idx?'wrong':''):''}"><input type="radio" name="${esc(mode+'-'+q.id)}" value="${idx}" ${mode==='exam'?`data-exam-q="${esc(q.id)}"`:`data-practice-q="${esc(q.id)}"`} ${choice===idx?'checked':''} ${reveal?'disabled':''}><span><strong>${String.fromCharCode(65+n)}.</strong> ${esc(q.options[idx])}</span></label>`).join('');}
function explanation(q,choice){return `<div class="explain"><strong class="${choice===q.answer?'good':'bad'}">${choice===q.answer?'✓ Trả lời đúng.':choice===undefined?'Chưa trả lời.':'Cần xem lại lập luận.'}</strong><p>Đáp án: <strong>${esc(q.options[q.answer])}</strong></p>${q.options.map((o,i)=>`<p><strong>${i===q.answer?'✓':'○'} ${esc(o)}</strong><br>${esc(q.reasons[i])}</p>`).join('')}<p>Ôn đúng bài: ${linkLesson(q.lesson)}</p><details><summary>Nguồn và phạm vi câu hỏi</summary><p>Câu hỏi và lựa chọn do ứng dụng biên soạn theo các nguồn sau.</p>${sourceRefs(q.refs)}</details></div>`;}
function practicePage(c='all',l='all',page='0'){let pool=D.questions.filter(q=>(c==='all'||c==='wrong'||q.chapter===c)&&(l==='all'||q.lesson===l)&&(c!=='wrong'||S.wrong[q.id]));const p=Math.max(0,parseInt(page)||0),start=p*10,subset=pool.slice(start,start+10);const essayPool=D.essays.filter(e=>c==='all'||c==='wrong'||e.lessons.some(id=>li(id)?.chapter===c));return `<div class="eyebrow">LUYỆN CHO ĐẾN KHI GIẢI THÍCH ĐƯỢC</div><h1>Thử trước. Hiểu sau phản hồi.</h1><p class="lead">Mỗi câu có bốn lựa chọn, một đáp án đúng và giải thích riêng cho từng lựa chọn. Kết quả đã xem được tính vào thống kê luyện tập.</p><div class="filters"><select id="practice-chapter" aria-label="Chọn chủ đề"><option value="all" ${c==='all'?'selected':''}>Toàn bộ học liệu</option><option value="wrong" ${c==='wrong'?'selected':''}>Chỉ câu sai cần ôn</option>${D.chapters.map(x=>`<option value="${esc(x.id)}" ${x.id===c?'selected':''}>${esc(x.title)}</option>`).join('')}</select><select id="practice-lesson" aria-label="Chọn bài"><option value="all">Tất cả bài trong chủ đề</option>${D.lessons.filter(x=>c==='all'||c==='wrong'||x.chapter===c).map(x=>`<option value="${esc(x.id)}" ${x.id===l?'selected':''}>${esc(x.id+' · '+x.title)}</option>`).join('')}</select></div><div class="row spread"><p class="count">${pool.length} câu phù hợp · trang ${p+1}/${Math.max(1,Math.ceil(pool.length/10))}</p><button data-action="practice-reset">Làm lại các câu đang hiển thị</button></div>${subset.map((q,i)=>{const v=practice[q.id]||{};return `<article class="question" id="${esc(q.id)}"><span class="tag">${start+i+1} · ${esc(q.level)}</span><span class="tag">${esc(q.lesson)}</span><h3>${esc(q.prompt)}</h3>${optionsHTML(q,v.choice,v.revealed,'practice')}${v.revealed?explanation(q,v.choice):`<button class="primary" data-action="check" data-id="${esc(q.id)}">Kiểm tra & giải thích</button>`}</article>`;}).join('')||'<div class="empty">Không có câu phù hợp. Câu sai sẽ xuất hiện sau khi bạn luyện tập hoặc nộp đề.</div>'}<div class="actions">${p>0?`<a class="pill" href="#practice/${esc(c)}/${esc(l)}/${p-1}">← Trang trước</a>`:''}${start+10<pool.length?`<a class="pill" href="#practice/${esc(c)}/${esc(l)}/${p+1}">Trang tiếp →</a>`:''}</div><div class="section-top"><h2>Luyện tự luận có gợi ý</h2></div>${essayPool.map(e=>`<article class="question"><span class="tag">Tự luận · rubric 10 điểm</span><h3>${esc(e.title)}</h3><p>${esc(e.prompt)}</p><label class="block" for="draft-${esc(e.id)}">Bài viết luyện tập của bạn</label><textarea id="draft-${esc(e.id)}" class="essay-text" data-note="essay-${esc(e.id)}" placeholder="Tự lập luận trước khi mở gợi ý…">${esc(S.notes['essay-'+e.id]||'')}</textarea><details><summary>Gợi ý từng bước trước khi xem lời giải</summary><ol>${e.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details><details><summary>Đáp án tham khảo & các ý cần có</summary><p>${esc(e.model)}</p>${rubricHTML(e,null,null)}${sourceRefs(e.refs)}</details></article>`).join('')||'<div class="notice">Chủ đề này có câu tự kiểm tra mở ở cuối mỗi bài. Bộ tự luận tổng hợp có 9 tình huống liên chương.</div>'}`;}
function matrixHTML(paper){const m=K.matrix(paper.questions);return `<div class="table-wrap"><table><thead><tr><th>Chủ đề</th>${K.levels.map(l=>`<th>${l}</th>`).join('')}<th>Tổng</th></tr></thead><tbody>${D.chapters.filter(c=>m[c.id]).map(c=>`<tr><td>${esc(c.title)}</td>${K.levels.map(l=>`<td>${m[c.id][l]}</td>`).join('')}<td>${m[c.id].total}</td></tr>`).join('')}<tr><th>Tổng</th>${K.levels.map(l=>`<th>${paper.questions.filter(q=>q.level===l).length}</th>`).join('')}<th>${paper.questions.length}</th></tr></tbody></table></div>`;}
function examLanding(){return `<div class="eyebrow">THI THỬ CÓ MA TRẬN</div><h1>40 trắc nghiệm. 3 tự luận.</h1><p class="lead">Ba đề có tổ hợp câu hỏi và bộ tự luận khác nhau. Đề tự luyện được tạo từ học liệu trong ứng dụng, chưa được xác nhận mô phỏng đề thật của giảng viên.</p>${S.activeExam?`<div class="notice"><strong>Bài thi ${esc(S.activeExam.name)} đang tiếp tục tính giờ.</strong><br><a class="btn" href="#exam">Tiếp tục bài đang làm →</a></div>`:''}<div class="filters"><label>Thời gian mỗi đề (phút) <input id="exam-minutes" type="number" min="5" max="360" value="90" style="width:100px"></label></div><div class="grid">${[0,1,2].map(n=>{const paper=K.makePaper(D,n,'preview-'+n);return `<div class="card"><div class="eyebrow">ĐỀ ${String(n+1).padStart(2,'0')}</div><h3>${['Tài nguyên & kiến trúc','Vận hành & dữ liệu','Phân tán & đánh giá'][n]}</h3><p>40 câu · 4 lựa chọn/câu<br>3 tự luận · có phân tích tình huống</p><p><small>Phủ ${Object.keys(K.matrix(paper.questions)).length} nhóm nội dung; mức độ xem trong ma trận.</small></p><button class="primary" data-action="start-exam" data-preset="${n}" ${S.activeExam?'disabled':''}>Bắt đầu đề ${n+1} →</button><button class="small" data-action="matrix" data-preset="${n}">Xem ma trận</button></div>`;}).join('')}</div><div class="notice">Trong khi thi, đáp án và rubric được ẩn đến khi nộp. Chấm tự động phần trắc nghiệm theo số câu đúng; tự luận tự chấm theo rubric. Không có chấm AI hoặc gửi bài viết ra ngoài. Đồng hồ tiếp tục khi đóng tab; mở lại sẽ khôi phục và nộp nếu đã hết giờ.</div><div class="section-top"><h2>Lịch sử thi</h2></div>${S.history.length?S.history.slice().reverse().map(e=>`<a class="card row spread" style="margin-bottom:12px" href="#result/${esc(e.id)}"><span><strong>${esc(e.name)}</strong><small class="block">${humanDate(e.submitted)}</small></span><span><strong>${e.grade.correct}/40</strong><small class="block">Trắc nghiệm · xem tự luận →</small></span></a>`).join(''):'<div class="empty">Bài thi đầu tiên của bạn sẽ xuất hiện ở đây.</div>'}`;}
function startExam(n){if(S.activeExam){go('#exam');return;}const minutes=Number($('#exam-minutes').value);if(!Number.isFinite(minutes)||minutes<5||minutes>360){toast('Thời gian cần từ 5 đến 360 phút.',true);return;}const now=Date.now(),paper=K.makePaper(D,n,'exam-'+now);S.activeExam={id:'exam-'+now,name:'Đề '+(n+1),preset:n,contentVersion:D.version,started:now,deadline:now+minutes*60000,paper,answers:{},essayText:{},self:{}};persist();go('#exam');}
function examPage(){const e=S.activeExam;if(!e)return '<h1>Không có bài thi đang làm</h1><a class="btn" href="#exams">Chọn đề thi →</a>';return `<div class="eyebrow">${esc(e.name)} · HỌC LIỆU ${esc(e.contentVersion)}</div><h1>Tập trung vào lập luận của bạn.</h1><p class="muted">Có thể chuyển khu vực rồi quay lại. Câu trả lời và bài viết tự lưu; hết giờ hệ thống tự nộp.</p><div class="exam-toolbar"><span>Thời gian còn lại</span><strong id="exam-clock">--:--</strong><span id="exam-answered"></span><button data-action="submit-dialog">Nộp bài</button></div><nav class="exam-nav" aria-label="Đi nhanh tới câu trắc nghiệm">${e.paper.questions.map((q,i)=>`<a href="#exam-q-${i}" data-scroll="exam-q-${i}" data-qnav="${esc(q.id)}" class="${e.answers[q.id]!==undefined?'answered':''}">${i+1}</a>`).join('')}</nav><h2>Phần I · 40 câu trắc nghiệm</h2>${e.paper.questions.map((q,i)=>`<article id="exam-q-${i}" class="question"><span class="tag">Câu ${i+1}/40</span><h3>${esc(q.prompt)}</h3>${optionsHTML(q,e.answers[q.id],false,'exam')}</article>`).join('')}<h2>Phần II · 3 câu tự luận</h2><p class="muted">Mỗi câu có rubric 10 điểm để tự đánh giá sau khi nộp. Điểm tự luận được báo riêng với trắc nghiệm.</p>${e.paper.essays.map((x,i)=>`<article class="question" id="exam-e-${i}"><span class="tag">Tự luận ${i+1}/3</span><h3>${esc(x.title)}</h3><p>${esc(x.prompt)}</p><label for="exam-text-${esc(x.id)}">Bài làm của bạn</label><textarea id="exam-text-${esc(x.id)}" class="essay-text" data-exam-essay="${esc(x.id)}" placeholder="Nêu giả định, phân tích cơ chế, đề xuất và giới hạn…">${esc(e.essayText[x.id]||'')}</textarea></article>`).join('')}<button class="primary" data-action="submit-dialog">Nộp bài và xem kết quả</button>`;}
function submitExam(auto=false){const e=S.activeExam;if(!e)return;e.submitted=Date.now();e.autoSubmitted=auto;e.grade=K.grade(e.paper.questions,e.answers);for(const q of e.paper.questions)recordAnswer(q,e.answers[q.id]);S.history.push(e);S.activeExam=null;persist();closeModal();go('#result/'+e.id);if(auto)toast('Đã hết giờ. Bài làm đã được nộp và lưu.',true);}
function tick(){const e=S.activeExam;if(!e)return;const seconds=Math.max(0,Math.ceil((e.deadline-Date.now())/1000));if($('#exam-clock'))$('#exam-clock').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;if($('#exam-answered'))$('#exam-answered').textContent=Object.keys(e.answers).length+'/40 đã chọn';if(seconds===0)submitExam(true);}
function rubricHTML(e,examId,self){return `<div class="table-wrap"><table class="rubric"><thead><tr><th>Các ý bắt buộc / tiêu chí</th><th>Tối đa</th>${examId?'<th>Bạn tự chấm</th>':''}</tr></thead><tbody>${e.criteria.map((c,i)=>`<tr><td>${esc(c.text)}</td><td>${c.max}</td>${examId?`<td><input aria-label="Điểm tiêu chí ${i+1} cho ${esc(e.title)}" type="number" min="0" max="${c.max}" step="0.5" value="${esc(self?.[i]??'')}" data-self-exam="${esc(examId)}" data-self-essay="${esc(e.id)}" data-criterion="${i}"></td>`:''}</tr>`).join('')}<tr><th>Tổng</th><th>10</th>${examId?`<th id="self-total-${esc(e.id)}">${self?Object.values(self).reduce((a,b)=>a+Number(b||0),0):0}/10</th>`:''}</tr></tbody></table></div>`;}
function resultPage(id){const e=S.history.find(h=>h.id===id);if(!e)return missing();const g=e.grade;return `<div class="eyebrow">${esc(e.name)} · NỘP ${humanDate(e.submitted)}</div><h1>Biết rõ chỗ cần học lại.</h1><div class="grid two"><div class="card"><div class="score">${g.correct}<small>/40</small></div><p>Trắc nghiệm · ${(g.score).toFixed(2)}/10<br><small>${e.autoSubmitted?'Tự nộp khi hết giờ.':'Đã nộp chủ động.'} Câu bỏ trống tính chưa đúng.</small></p></div><div class="card"><h3>Tự luận: tự đánh giá theo rubric</h3><p>3 câu × 10 điểm, báo riêng với điểm trắc nghiệm. Ứng dụng không tự đặt tỷ trọng thi chính thức.</p><p id="essay-overall">${essayOverall(e)}</p><button data-action="export-result" data-id="${esc(e.id)}">Xuất bản làm & kết quả</button></div></div><div class="section-top"><h2>Độ chính xác theo chủ đề</h2><a href="#practice/wrong/all/0">Luyện lại câu sai →</a></div><div class="table-wrap"><table><thead><tr><th>Chủ đề</th><th>Đúng / số câu</th><th>Ôn lại</th></tr></thead><tbody>${Object.entries(g.byChapter).sort((a,b)=>a[1].correct/a[1].total-b[1].correct/b[1].total).map(([cid,v])=>`<tr><td>${esc(ch(cid)?.title||cid)}</td><td>${v.correct}/${v.total} · ${Math.round(100*v.correct/v.total)}%</td><td><a href="#practice/${esc(cid)}/all/0">Luyện chủ đề</a></td></tr>`).join('')}</tbody></table></div><details><summary>Ma trận đề đã làm</summary>${matrixHTML(e.paper)}</details><h2 style="margin-top:32px">Đáp án & giải thích trắc nghiệm</h2>${e.paper.questions.map((q,i)=>`<details class="question"><summary>Câu ${i+1} · ${e.answers[q.id]===q.answer?'✓ Đúng':e.answers[q.id]===undefined?'Bỏ trống':'Cần ôn'} · ${esc(q.prompt)}</summary>${optionsHTML(q,e.answers[q.id],true,'result')}${explanation(q,e.answers[q.id])}</details>`).join('')}<h2 style="margin-top:32px">Tự luận: đối chiếu và tự chấm</h2>${e.paper.essays.map((x,i)=>`<article class="question"><span class="tag">Tự luận ${i+1}</span><h3>${esc(x.title)}</h3><p>${esc(x.prompt)}</p><h4>Bài bạn đã nộp</h4><div class="notice" style="white-space:pre-wrap">${esc(e.essayText[x.id]||'(Chưa viết bài)')}</div><details><summary>Đáp án tham khảo</summary><p>${esc(x.model)}</p></details>${rubricHTML(x,e.id,e.self?.[x.id])}<label for="reflect-${esc(x.id)}">Tự nhận xét: ý nào còn thiếu?</label><textarea class="note" id="reflect-${esc(x.id)}" data-note="reflect-${esc(e.id)}-${esc(x.id)}">${esc(S.notes['reflect-'+e.id+'-'+x.id]||'')}</textarea><p>Ôn lại: ${x.lessons.map(linkLesson).join(' · ')}</p><details><summary>Nguồn đối chiếu</summary>${sourceRefs(x.refs)}</details></article>`).join('')}`;}
function essayOverall(e){const vals=e.paper.essays.map(x=>{const s=e.self?.[x.id]||{};return {sum:Object.values(s).reduce((a,b)=>a+Number(b||0),0),complete:x.criteria.every((_,i)=>s[i]!==undefined)};});return `Tự chấm hiện tại: ${vals.reduce((a,b)=>a+b.sum,0)}/30 · ${vals.filter(x=>x.complete).length}/3 câu đã điền đủ tiêu chí.`;}
function reviewPage(){const wrong=D.questions.filter(q=>S.wrong[q.id]),saved=D.lessons.filter(l=>S.saved[l.id]),weak=Object.entries(S.stats).filter(([id,v])=>li(id)&&v.total&&v.correct/v.total<.75).sort((a,b)=>a[1].correct/a[1].total-b[1].correct/b[1].total);return `<div class="eyebrow">ÔN TẬP CHỦ ĐỘNG</div><h1>Quay lại đúng chỗ còn vướng.</h1><p class="lead">Danh sách dựa trên câu đã được chấm, không suy mức hiểu từ thời gian mở trang. Làm đúng lại sẽ đưa câu ra khỏi hàng chờ sai; lịch sử thống kê vẫn giữ.</p><div class="actions"><a class="btn" href="#practice/wrong/all/0">Luyện ${wrong.length} câu sai →</a></div><div class="grid two"><div class="card"><h3>Bài có tỷ lệ đúng dưới 75%</h3>${weak.length?`<ul>${weak.map(([id,v])=>`<li>${linkLesson(id)}<br><small>${v.correct}/${v.total} lượt trả lời đúng</small></li>`).join('')}</ul>`:'<p class="muted">Chưa có bài thuộc nhóm này. Hãy thử luyện tập để có dữ liệu.</p>'}</div><div class="card"><h3>Bài bạn đã lưu</h3>${saved.length?`<ul>${saved.map(l=>`<li>${linkLesson(l.id)}</li>`).join('')}</ul>`:'<p class="muted">Dùng “Lưu bài” để tạo danh sách của riêng bạn.</p>'}</div></div><div class="section-top"><h2>Câu sai đang chờ</h2></div>${wrong.map(q=>`<div class="card" style="margin-bottom:12px"><p>${esc(q.prompt)}</p><a href="#practice/${esc(q.chapter)}/${esc(q.lesson)}/0">Luyện đúng bài ${esc(q.lesson)} →</a></div>`).join('')||'<div class="empty">Hiện không có câu sai chờ ôn.</div>'}<div class="section-top"><h2>Ghi chú bài học</h2></div>${Object.entries(S.notes).filter(([id,v])=>li(id)&&v.trim()).map(([id,v])=>`<div class="card" style="margin-bottom:12px">${linkLesson(id)}<p style="white-space:pre-wrap">${esc(v)}</p></div>`).join('')||'<p class="muted">Ghi chú sẽ hiện sau khi bạn viết trong trang bài học.</p>'}`;}
function sourcesPage(){return `<div class="eyebrow">24 TÀI LIỆU · NGUỒN GIỮ NGUYÊN TRONG GÓI</div><h1>Đọc lại đúng nơi kiến thức bắt đầu.</h1><p class="lead">Mở trang gốc khi cần kiểm tra sơ đồ, công thức hoặc ngữ cảnh. Văn bản trích xuất chỉ hỗ trợ tra cứu; hình ảnh trong PDF có thể chứa thông tin không có trong phần chữ.</p><details class="notice" open><summary>Phạm vi, cách đánh số và các giới hạn đã ghi nhận</summary><ul>${(D.notes||BASE.notes).map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details><div class="table-wrap"><table><thead><tr><th>Tài liệu thực sự mở được</th><th>Vai trò</th><th>Số trang</th><th>Tra cứu</th></tr></thead><tbody>${D.documents.map(d=>`<tr><td>${esc(d.file)}${d.imageHeavy?.length?`<br><small class="warning-dot">Ít chữ/chủ yếu hình ở trang PDF: ${d.imageHeavy.join(', ')}. Mở bản gốc để đọc.</small>`:''}</td><td>${esc(d.role||'Bổ sung')}</td><td>${d.pages}</td><td><button class="small" data-action="source" data-file="${esc(d.file)}" data-page="1">Mở PDF</button></td></tr>`).join('')}</tbody></table></div><div class="section-top"><h2>Đối chiếu tới từng trang</h2><a href="docs/doi-chieu.csv" download>Tải bảng CSV gốc</a></div><label for="coverage-file">Chọn tài liệu để xem liên kết bài</label><select id="coverage-file" style="width:100%">${D.documents.map(d=>`<option value="${esc(d.file)}">${esc(d.file)}</option>`).join('')}</select><div id="coverage-table"></div><div class="notice">Tất cả trang slide được gắn vào cụm bài liên quan. “Có liên kết” cho biết nơi học chủ đề, không chứng minh từng dòng/hình đã được giảng thành một tiểu mục độc lập. Các phần sách ngoài phạm vi slide được giữ để đọc bổ trợ. Số mục gốc của sách xem tại trang PDF 8–15 và mục lục đầu chương.</div>`;}
function coverage(){if(!$('#coverage-table'))return;const file=$('#coverage-file').value,rows=(D.coverage||[]).filter(r=>r.file===file);$('#coverage-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Trang PDF</th><th>Trang in</th><th>Bài liên quan</th><th>Đối chiếu</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="small" data-action="source" data-file="${esc(file)}" data-page="${r.pdfPage}">${r.pdfPage} ↗</button></td><td>${esc(r.printedPage)||'Xem bản gốc'}</td><td>${r.lessons.map(linkLesson).join('<br>')||'Bìa/mục lục hoặc phần sách bổ trợ ngoài cụm bài'}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="notice">Tài liệu bổ sung chưa có bảng đối chiếu trang. Hãy thêm coverage khi biên soạn gói cập nhật.</p>';}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('cloudlab.files.v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('pdfs',{keyPath:'name'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function pdfStore(op,value){const db=await openDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('pdfs',op==='put'?'readwrite':'readonly'),store=tx.objectStore('pdfs'),req=op==='put'?store.put(value):op==='list'?store.getAll():store.get(value);req.onsuccess=()=>{if(op!=='put')resolve(req.result);};tx.oncomplete=()=>{if(op==='put')resolve(true);};req.onerror=()=>reject(req.error);tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
async function showSource(file,page){const doc=D.documents.find(d=>d.file===file);page=Math.max(1,Math.min(doc?.pages||9999,parseInt(page)||1));let url='sources/'+encodeURIComponent(file);try{const record=await pdfStore('get',file);if(record?.blob){if(sourceURL)URL.revokeObjectURL(sourceURL);sourceURL=URL.createObjectURL(record.blob);url=sourceURL;}}catch(e){/* PDF nguyên gói vẫn mở qua đường local. */}showModal(`<div class="eyebrow">NGUỒN GỐC · TRANG PDF ${page}${doc?.pages?' / '+doc.pages:''}</div><h2 style="font-size:20px">${esc(file)}</h2><div class="row"><label>Đến trang <input id="pdf-page" type="number" min="1" max="${doc?.pages||9999}" value="${page}" style="width:90px"></label><button data-action="pdf-jump" data-file="${esc(file)}">Mở trang</button><a href="${esc(url)}#page=${page}" target="_blank" rel="noopener">Mở PDF ở tab riêng ↗</a></div><p class="muted">Số nhập là trang PDF, không phải trang in. Trình đọc của trình duyệt quyết định hỗ trợ nhảy trang; nếu chưa nhảy, nhập số trong thanh công cụ PDF.</p><iframe class="pdf-frame" title="${esc(file)} trang PDF ${page}" src="${esc(url)}#page=${page}"></iframe><details><summary>Văn bản trích xuất ở trang này (không thay sơ đồ gốc)</summary><pre style="max-height:35vh">${esc(doc?.texts?.[page-1]||'Chưa có văn bản trích xuất hoặc trang chủ yếu là ảnh. Đọc PDF ở khung trên.')}</pre></details>`);}
function settingsPage(){return `<div class="eyebrow">DỮ LIỆU TRONG TAY BẠN</div><h1>Sao lưu. Bổ sung. Tiếp tục học.</h1><p class="lead">Tiến độ, ghi chú, câu sai và lịch sử thi lưu trong trình duyệt của bạn. Không có tài khoản, analytics hay chấm bài trực tuyến.</p><div class="grid two" style="margin-top:25px"><div class="card"><h3>Dữ liệu cá nhân</h3><p>Xuất JSON trước khi đổi máy, đổi trình duyệt, dọn dữ liệu trình duyệt hoặc cập nhật lớn.</p><div class="actions"><button class="primary" data-action="backup">Xuất sao lưu đầy đủ</button><button data-action="import-backup">Nhập sao lưu</button><input id="backup-file" type="file" accept=".json,application/json" hidden></div><small>Nhập là thay dữ liệu cá nhân bằng bản sao lưu. Trước khi nhập, ứng dụng tự tải bản hiện tại xuống để có thể quay lại. PDF bổ sung không nằm trong JSON; giữ bản PDF riêng.</small></div><div class="card"><h3>Cập nhật học liệu theo ID ổn định</h3><p>Nhập gói JSON đã biên soạn và dẫn nguồn; bài có cùng ID được cập nhật, bài mới được thêm. Tiến độ và ghi chú giữ theo ID.</p><div class="actions"><button data-action="import-content">Nhập gói học liệu</button><button data-action="export-content">Xuất học liệu hiện tại</button><input id="content-file" type="file" accept=".json,application/json" hidden></div><small>Học liệu v${esc(D.version)}. Đọc <a href="docs/CAP_NHAT.md" target="_blank">hướng dẫn cấu trúc và kiểm chứng</a>. Thêm PDF không tự sinh bài/đáp án; cần biên soạn và đối chiếu nội dung trước.</small></div></div><div class="card" style="margin-top:22px"><h3>Thêm PDF để tra nguồn offline</h3><p>Chọn PDF bổ sung; tệp được giữ trong bộ nhớ IndexedDB của trình duyệt. Gói học liệu mới dùng đúng tên tệp này trong refs và documents.</p><label for="extra-pdf">Chọn một hoặc nhiều PDF</label><input id="extra-pdf" type="file" accept="application/pdf,.pdf" multiple><p class="muted">Không thực hiện OCR hay diễn giải tự động. Nếu dung lượng trình duyệt không đủ, đặt tệp vào thư mục sources của gói và thêm metadata vào học liệu.</p><div id="extra-files"></div></div><div class="notice warn"><strong>Chuyển tiến độ từ bản local.</strong> Ở bản local, xuất sao lưu JSON rồi nhập tại trang này. Tiến độ trên web vẫn lưu riêng theo trình duyệt và thiết bị; chưa đồng bộ qua tài khoản. Giữ bản sao lưu trước khi đổi máy hoặc dọn dữ liệu trình duyệt.</div><div class="card"><h3>Bản web học tập</h3><ul><li>Nội dung và 24 PDF được phục vụ trên web học tập. Trang không tải font/CDN hoặc dùng API chấm AI. Cần Internet để mở/tải trang và nguồn; chưa có bộ nhớ offline cho bản web.</li><li>Chấm trắc nghiệm offline; tự luận có rubric để tự chấm, không chấm AI.</li><li>Có mã nguồn HTML/CSS/JS và dữ liệu JSON tách riêng.</li><li>Bản web hiện tại được chia sẻ công khai. Ghi chú và tiến độ học vẫn ở trình duyệt, không tự đồng bộ lên máy khác.</li><li>Bản ZIP local đã bàn giao vẫn hoạt động độc lập. Bản web này không yêu cầu cài launcher.</li></ul><a href="HUONG_DAN.html" target="_blank">Mở hướng dẫn bản web & chuyển tiến độ ↗</a></div>`;}
async function listExtra(){const target=$('#extra-files');if(!target)return;try{const rows=await pdfStore('list');target.innerHTML=rows.map(r=>`<p>${esc(r.name)} · ${(r.blob.size/1048576).toFixed(1)} MiB <button class="small" data-action="source" data-file="${esc(r.name)}" data-page="1">Mở</button><button class="small" data-action="download-pdf" data-file="${esc(r.name)}">Tải bản sao</button></p>`).join('')||'<small>Chưa thêm PDF ngoài gói.</small>';}catch(e){target.textContent='Không truy cập được kho PDF trên trình duyệt này. Dùng thư mục sources để bổ sung.';}}
function download(name,data,mime='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(){download('CloudLab-sao-luu-'+new Date().toISOString().slice(0,10)+'.json',{format:'cloudlab-backup',schemaVersion:1,exported:new Date().toISOString(),personal:S,content:D});toast('Đã tạo bản sao lưu. Giữ riêng các PDF bổ sung.');}
async function readJSON(file,max=15000000){if(!file)throw Error('Chưa chọn tệp.');if(file.size>max)throw Error('Tệp vượt giới hạn 15 MB.');return JSON.parse(await file.text());}
async function importBackup(file){try{const b=await readJSON(file),personal=K.validateBackup(b.personal||b),content=b.content?K.mergeContent(BASE,b.content):D;backup();const packed=JSON.stringify(content),p=JSON.stringify(personal);const oldContent=localStorage.getItem(CONTENT),oldPersonal=localStorage.getItem(KEY);try{localStorage.setItem(CONTENT,packed);localStorage.setItem(KEY,p);}catch(e){if(oldContent===null)localStorage.removeItem(CONTENT);else localStorage.setItem(CONTENT,oldContent);if(oldPersonal===null)localStorage.removeItem(KEY);else localStorage.setItem(KEY,oldPersonal);throw e;}D=content;S=personal;storageError='';practice={};buildIndex();render();toast('Đã nhập sao lưu và giữ một bản của dữ liệu trước đó.');tick();}catch(e){toast('Không nhập được: '+e.message,true);}}
async function importContent(file){try{const pack=await readJSON(file),next=K.mergeContent(D,pack);for(let n=0;n<3;n++)K.makePaper(next,n,'validation');localStorage.setItem(CONTENT,JSON.stringify(next));D=next;practice={};buildIndex();render();toast('Đã cập nhật học liệu; tiến độ giữ nguyên theo ID.');}catch(e){toast('Không cập nhật được: '+e.message,true);}}
function render(){const parts=location.hash.replace(/^#/,'').split('/'),route=parts[0]||'home',id=parts[1];nav(route,id);const app=$('#app');try{app.innerHTML=(storageError?`<div class="notice error">${esc(storageError)} <button data-action="export-raw">Xuất dữ liệu lưu gốc</button></div>`:'')+({home:()=>home(),courses:()=>coursePage(),chapter:()=>chapterPage(id),lesson:()=>lessonPage(id),glossary:()=>glossaryPage(),practice:()=>practicePage(parts[1],parts[2],parts[3]),exams:()=>examLanding(),exam:()=>examPage(),result:()=>resultPage(id),review:()=>reviewPage(),sources:()=>sourcesPage(),settings:()=>settingsPage()}[route]||missing)();}catch(e){app.innerHTML=`<h1>Không mở được khu vực này</h1><p>${esc(e.message)}</p><a href="#settings">Mở sao lưu & cập nhật</a>`;console.error(e);}document.body.classList.remove('menu-open');filterTerms();refreshLabs();coverage();listExtra();tick();window.scrollTo(0,0);}

document.addEventListener('click',async ev=>{
 const scroll=ev.target.closest('[data-scroll]');if(scroll){ev.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 const a=ev.target.closest('[data-action]');if(!a){const link=ev.target.closest('a[href^="#"]');if(link&&$('#modal').open)closeModal();return;}const d=a.dataset;switch(d.action){
 case 'search':showSearch();break;case 'close':closeModal();break;case 'navigate':ev.preventDefault();go(d.hash);break;case 'term':showTerm(d.id);break;
 case 'source':await showSource(d.file,d.page);break;case 'pdf-jump':await showSource(d.file,$('#pdf-page').value);break;
 case 'done':S.done[d.id]=!S.done[d.id];persist();render();break;case 'save':S.saved[d.id]=!S.saved[d.id];persist();a.textContent=S.saved[d.id]?'★ Đã lưu':'☆ Lưu bài';break;
 case 'print':window.print();break;
 case 'check':{const q=D.questions.find(q=>q.id===d.id),v=practice[d.id]||{};if(v.choice===undefined){toast('Chọn một phương án trước khi xem lời giải.');return;}if(!v.revealed){v.revealed=true;practice[d.id]=v;recordAnswer(q,v.choice);}const y=window.scrollY;render();window.scrollTo(0,y);break;}
 case 'practice-reset':{for(const q of document.querySelectorAll('[data-practice-q]'))delete practice[q.dataset.practiceQ];const y=window.scrollY;render();window.scrollTo(0,y);toast('Đã mở lượt làm mới. Lịch sử thống kê vẫn giữ.');break;}
 case 'matrix':{const p=K.makePaper(D,+d.preset,'preview-'+d.preset);showModal(`<h2>Ma trận đề ${Number(d.preset)+1}</h2><p>Ưu tiên mỗi nhóm nội dung có ít nhất một câu; số câu còn lại ưu tiên các chương trục slide. Bảng dưới là số lượng thực tế của đề, tổng đúng 40 câu. Bộ tự luận bổ sung tình huống liên chương.</p>${matrixHTML(p)}<h3>Tự luận (chỉ tiêu đề)</h3><ol>${p.essays.map(e=>`<li>${esc(e.title)}</li>`).join('')}</ol>`);break;}
 case 'start-exam':startExam(+d.preset);break;
 case 'submit-dialog':{const e=S.activeExam;if(!e)break;const missing=40-Object.keys(e.answers).length;showModal(`<h2>Nộp bài thi?</h2><p>Đã chọn ${40-missing}/40 câu trắc nghiệm. ${missing?'Còn '+missing+' câu bỏ trống; chúng sẽ tính chưa đúng.':''}</p><p>${e.paper.essays.filter(x=>(e.essayText[x.id]||'').trim()).length}/3 câu tự luận có bài viết. Sau khi nộp, bài làm được lưu và lời giải sẽ hiện.</p><div class="actions"><button class="primary" data-action="submit-now">Nộp và chấm trắc nghiệm</button><button data-action="close">Tiếp tục làm</button></div>`);break;}
 case 'submit-now':submitExam(false);break;
 case 'backup':backup();break;case 'import-backup':$('#backup-file').click();break;case 'import-content':$('#content-file').click();break;case 'export-content':download('CloudLab-content.json',D);break;
 case 'export-raw':download('CloudLab-du-lieu-goc.json',{personal:localStorage.getItem(KEY),content:localStorage.getItem(CONTENT)});break;
 case 'export-result':{const e=S.history.find(e=>e.id===d.id);if(e)download('CloudLab-'+e.id+'.json',e);break;}
 case 'download-pdf':try{const r=await pdfStore('get',d.file);if(r)download(r.name,r.blob,'application/pdf');}catch(e){toast('Không tải được PDF: '+e.message,true);}break;
 }
});
document.addEventListener('input',ev=>{const el=ev.target,d=el.dataset;if(d.note){S.notes[d.note]=el.value;persist();}if(d.examEssay&&S.activeExam){S.activeExam.essayText[d.examEssay]=el.value;persist();}if(d.lab)refreshLabs();if(el.id==='term-search')filterTerms();if(el.id==='global-search')search();if(d.selfExam){const e=S.history.find(e=>e.id===d.selfExam),essay=e?.paper.essays.find(x=>x.id===d.selfEssay);if(!e||!essay)return;e.self??={};e.self[essay.id]??={};const i=Number(d.criterion),n=Number(el.value),max=essay.criteria[i].max;if(el.value===''){delete e.self[essay.id][i];}else if(Number.isFinite(n)&&n>=0&&n<=max){e.self[essay.id][i]=n;}else{toast('Điểm tiêu chí phải từ 0 đến '+max,true);el.value=e.self[essay.id][i]??'';}persist();$('#self-total-'+essay.id).textContent=Object.values(e.self[essay.id]).reduce((a,b)=>a+Number(b||0),0)+'/10';$('#essay-overall').textContent=essayOverall(e);}});
document.addEventListener('change',async ev=>{const el=ev.target,d=el.dataset;if(d.practiceQ){practice[d.practiceQ]??={};practice[d.practiceQ].choice=Number(el.value);}if(d.examQ&&S.activeExam){S.activeExam.answers[d.examQ]=Number(el.value);persist();document.querySelector(`[data-qnav="${CSS.escape(d.examQ)}"]`)?.classList.add('answered');tick();}if(el.id==='term-chapter')filterTerms();if(el.id==='coverage-file')coverage();if(el.id==='practice-chapter')go('#practice/'+el.value+'/all/0');if(el.id==='practice-lesson')go('#practice/'+$('#practice-chapter').value+'/'+el.value+'/0');if(el.id==='backup-file')await importBackup(el.files[0]);if(el.id==='content-file')await importContent(el.files[0]);if(el.id==='extra-pdf'){for(const file of el.files){try{if(file.size>150*1048576)throw Error('Giới hạn mỗi PDF là 150 MiB.');const sig=await file.slice(0,5).text();if(sig!=='%PDF-')throw Error('Không thấy chữ ký PDF.');await pdfStore('put',{name:file.name,blob:file,added:Date.now()});toast('Đã giữ PDF: '+file.name);}catch(e){toast('Không thêm được '+file.name+': '+e.message,true);}}await listExtra();}});
$('#menu').addEventListener('click',()=>document.body.classList.toggle('menu-open'));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch();}});
window.addEventListener('hashchange',()=>{closeModal();render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{S=K.validateBackup(JSON.parse(e.newValue));toast('Đã đồng bộ thay đổi từ tab CloudLab khác.');render();}catch(err){toast('Dữ liệu từ tab khác chưa hợp lệ: '+err.message,true);}}});
window.addEventListener('beforeunload',()=>{persist();});
buildIndex();render();setInterval(tick,1000);
